+static const char* const COMMA_SEPARATOR = ", ";
+
+void BCEscapeAnalyzer::dump_arg_set(const VectorSet &set) {
+  tty->print("{");
+  const char* sep = "";
+  for (int i = 0; i < _arg_size; i++) {
+    if (set.test(i)) {
+      tty->print("%s%d", sep, i);
+      sep = COMMA_SEPARATOR;
+    }
+  }
+  tty->print("}");
+}
